/*
 * O card do painel e as primitivas de layout do miolo. São POJOs com `view`
 * (formato de componente que o Mithril aceita), tipados como `any` para o JSX
 * aceitá-los.
 *
 * Estados do card de um recurso (CardDef com `master`):
 * - ligado: a chave do cabeçalho ligada e o miolo à vista;
 * - desligado: só o cabeçalho (título, o que faz, a chave) — o miolo some;
 * - trancado: falta uma extensão (ou outro requisito); a chave fica travada e
 *   o motivo aparece no lugar do miolo.
 */
import app from 'flarum/admin/app';
import Link from 'flarum/common/components/Link';
import { extensionInstalled, extensionName, getBool, missingExtension, trans } from '../util';
import { AdminSwitch } from './AdminSwitch';
import { setBool } from './AdminToggle';
const KEY = 'lcoy-roselle.admin.settings.shell';

/** Por que o card está trancado, ou `null`. */
export const lockReason = card => {
  const missing = missingExtension(card.extensions);
  if (missing) {
    return {
      extension: missing,
      text: extensionInstalled(missing) ? trans(`${KEY}.extension_disabled`, 'Precisa da extensão {name}, que está instalada mas desligada.', {
        name: extensionName(missing)
      }) : trans(`${KEY}.extension_missing`, 'Precisa da extensão {name}, que não está instalada.', {
        name: extensionName(missing)
      })
    };
  }
  const reason = card.lockedBy?.() ?? null;
  return reason ? {
    text: reason
  } : null;
};
let savingMaster = null;
export const AdminCard = {
  view({
    attrs: {
      card,
      groupLabel
    }
  }) {
    const lock = lockReason(card);
    const hasMaster = !!card.master;
    const on = hasMaster ? !lock && getBool(card.master) : !lock;
    const titleId = `CanelaAdmin-card-${card.id}-title`;
    const descId = `CanelaAdmin-card-${card.id}-desc`;
    const body = on && card.body ? card.body() : null;
    return m("section", {
      id: `CanelaAdmin-card-${card.id}`,
      className: `CanelaAdmin-card${hasMaster ? ' is-feature' : ''}${hasMaster && !on ? ' is-off' : ''}${lock ? ' is-locked' : ''}${body ? '' : ' is-empty'}`,
      "aria-labelledby": titleId
    }, m("header", {
      className: "CanelaAdmin-card-header"
    }, m("span", {
      className: "CanelaAdmin-card-icon"
    }, m("i", {
      className: card.icon,
      "aria-hidden": "true"
    })), m("div", {
      className: "CanelaAdmin-card-heading"
    }, m("h3", {
      className: "CanelaAdmin-card-title",
      id: titleId
    }, card.title(), groupLabel && m("span", {
      className: "CanelaAdmin-card-group"
    }, groupLabel)), card.description && m("p", {
      className: "CanelaAdmin-card-desc",
      id: descId
    }, card.description())), m("span", {
      className: "CanelaAdmin-card-saved",
      "aria-live": "polite"
    }, m("i", {
      className: "fas fa-check",
      "aria-hidden": "true"
    }), trans(`${KEY}.saved`, 'Salvo')), hasMaster && m("div", {
      className: "CanelaAdmin-card-master"
    }, m("span", {
      className: "CanelaAdmin-card-state"
    }, lock ? trans(`${KEY}.locked`, 'Indisponível') : on ? trans(`${KEY}.on`, 'Ativo') : trans(`${KEY}.off`, 'Inativo')), m(AdminSwitch, {
      state: on,
      disabled: !!lock,
      saving: savingMaster === card.master,
      label: card.title(),
      describedBy: card.description ? descId : undefined,
      onchange: checked => {
        savingMaster = card.master;
        setBool(card.master, checked).finally(() => {
          savingMaster = null;
          m.redraw();
        });
      }
    }))), lock && m("div", {
      className: "CanelaAdmin-card-lock"
    }, m("i", {
      className: lock.extension ? 'fas fa-plug-circle-xmark' : 'fas fa-lock',
      "aria-hidden": "true"
    }), m("span", null, lock.text), lock.extension && extensionInstalled(lock.extension) && m(Link, {
      className: "CanelaAdmin-card-lockLink",
      href: app.route('extension', {
        id: lock.extension
      })
    }, trans(`${KEY}.open_extension`, 'Abrir a extensão'))), body && m("div", {
      className: "CanelaAdmin-card-body"
    }, body));
  }
};

/** Aviso em destaque dentro de um card: dependências, efeitos colaterais. */
export const AdminNotice = {
  view({
    attrs: {
      icon = 'fas fa-circle-info'
    },
    children
  }) {
    return m("p", {
      className: "CanelaAdmin-notice"
    }, m("i", {
      className: icon,
      "aria-hidden": "true"
    }), m("span", null, children));
  }
};
export const SubDivider = {
  view() {
    return m("div", {
      className: "CanelaAdmin-subDivider"
    });
  }
};

/** Opções que dependem da de cima, recuadas num bloco. */
export const AdminSubGroup = {
  view({
    children
  }) {
    return m("div", {
      className: "CanelaAdmin-subGroup"
    }, children);
  }
};

/** Um título pequeno que separa blocos dentro de um card. */
export const SubTitle = {
  view({
    children
  }) {
    return m("h4", {
      className: "CanelaAdmin-subTitle"
    }, children);
  }
};
flarum.reg.add('lcoy-roselle', 'admin/components/AdminCard', { lockReason: lockReason,AdminCard: AdminCard,AdminNotice: AdminNotice,SubDivider: SubDivider,AdminSubGroup: AdminSubGroup,SubTitle: SubTitle, });